const cloud = require('wx-server-sdk')
cloud.init({ env: cloud.DYNAMIC_CURRENT_ENV })

const db = cloud.database()
const _ = db.command

const usersCol = db.collection('xiaoyouxi')
const reviewsCol = db.collection('game_reviews')
const counterCol = db.collection('id_counter')

function formatDate(d) {
  return d.getFullYear().toString() +
    String(d.getMonth() + 1).padStart(2, '0') +
    String(d.getDate()).padStart(2, '0') +
    String(d.getHours()).padStart(2, '0') +
    String(d.getMinutes()).padStart(2, '0') +
    String(d.getSeconds()).padStart(2, '0')
}

function maskNickName(openid) {
  if (!openid) return '微信用户'
  return '玩家' + openid.substring(openid.length - 4)
}

async function loginImpl(openid) {
  let user = null
  try {
    const res = await usersCol.where({ _openid: openid }).limit(1).get()
    if (res.data && res.data.length > 0) {
      user = res.data[0]
    }
  } catch (e) {}

  if (!user) {
    try {
      const res2 = await usersCol.where({ openid: openid }).limit(1).get()
      if (res2.data && res2.data.length > 0) user = res2.data[0]
    } catch (e) {}
  }

  if (user) {
    const updates = {}
    if (!user.userId) updates.userId = 'wj' + formatDate(new Date()) + '0001'
    if (!user.nickName || user.nickName === '微信用户') updates.nickName = maskNickName(openid)
    if (!user.openid) updates.openid = openid
    if (Object.keys(updates).length > 0) {
      updates.updatedAt = db.serverDate()
      await usersCol.doc(user._id).update({ data: updates })
      for (var k in updates) user[k] = updates[k]
    }
    return { code: 0, message: 'ok', data: user }
  }

  const newDoc = {
    userId: 'wj' + formatDate(new Date()) + '0001',
    nickName: maskNickName(openid),
    openid: openid,
    level: 1,
    totalScore: 0,
    challenge1024: { level: false, not_lock: false },
    challenge2048: { level: false, not_lock: false },
    challenge4096: { level: false, not_lock: false },
    challenge8192: { level: false, not_lock: false },
    updatedAt: db.serverDate()
  }

  try {
    const addRes = await usersCol.add({ data: newDoc })
    newDoc._id = addRes._id
    newDoc._openid = openid
    return { code: 0, message: 'ok', data: newDoc }
  } catch (addErr) {
    const retryRes = await usersCol.where({ _openid: openid }).limit(1).get()
    if (retryRes.data && retryRes.data.length > 0) {
      return { code: 0, message: 'ok', data: retryRes.data[0] }
    }
    throw addErr
  }
}

async function getUserDataImpl(openid) {
  try {
    const res = await usersCol.where({ _openid: openid }).limit(1).get()
    if (res.data && res.data.length > 0) {
      return { code: 0, message: 'ok', data: res.data[0] }
    }
  } catch (e) {}
  return { code: 0, message: 'ok', data: null }
}

async function updateGameImpl(openid, event) {
  const updateData = {}
  if (typeof event.level === 'number') updateData.level = event.level
  if (typeof event.totalScore === 'number') updateData.totalScore = event.totalScore

  const chFields = ['challenge1024', 'challenge2048', 'challenge4096', 'challenge8192']
  for (let i = 0; i < chFields.length; i++) {
    const f = chFields[i]
    if (event[f] && typeof event[f] === 'object') {
      updateData[f] = { level: !!event[f].level, not_lock: !!event[f].not_lock }
    }
  }

  if (Object.keys(updateData).length === 0) return { code: 0, message: 'ok', data: null }
  updateData.updatedAt = db.serverDate()

  const targetId = event.cloudUserId || ''
  if (targetId) {
    try {
      await usersCol.doc(targetId).update({ data: updateData })
      return { code: 0, message: 'ok' }
    } catch (e) {
      console.warn('[updateGame] cloudUserId failed:', e.message)
    }
  }

  try {
    const res = await usersCol.where({ _openid: openid }).limit(1).get()
    if (res.data && res.data.length > 0) {
      await usersCol.doc(res.data[0]._id).update({ data: updateData })
      return { code: 0, message: 'ok' }
    }
  } catch (e) {}
  return { code: 0, message: 'user not found', data: null }
}

async function getRankingImpl(openid, event) {
  const sortBy = event.sortBy === 'level' ? 'level' : 'totalScore'
  const limit = Math.min(event.limit || 50, 100)

  try {
    const res = await usersCol.orderBy(sortBy, 'desc').limit(limit).get()
    const list = (res.data || []).map(u => ({
      _id: u._id,
      nickName: u.nickName || '玩家',
      level: u.level || 1,
      totalScore: u.totalScore || 0
    }))
    return { code: 0, message: 'ok', data: list }
  } catch (e) {
    return { code: -1, message: e.message, data: [] }
  }
}

async function saveReviewImpl(openid, event) {
  const score = parseInt(event.score) || 0
  const comment = (event.comment || '').toString().substring(0, 200)

  if (score < 1 || score > 5) {
    return { code: -1, message: 'score must be 1-5' }
  }

  let userDoc = null
  try {
    const res = await usersCol.where({ _openid: openid }).limit(1).get()
    if (res.data && res.data.length > 0) userDoc = res.data[0]
  } catch (e) {
    console.warn('[saveReview] _openid query failed:', e.message)
  }

  if (!userDoc) {
    try {
      const res2 = await usersCol.where({ openid: openid }).limit(1).get()
      if (res2.data && res2.data.length > 0) userDoc = res2.data[0]
    } catch (e2) {
      console.warn('[saveReview] openid field query failed:', e2.message)
    }
  }

  if (!userDoc) {
    console.log('[saveReview] user not found, auto-creating...')
    try {
      const addRes = await usersCol.add({
        data: {
          userId: 'wj' + formatDate(new Date()) + '0001',
          nickName: maskNickName(openid),
          openid: openid,
          level: 1,
          totalScore: 0,
          challenge1024: { level: false, not_lock: false },
          challenge2048: { level: false, not_lock: false },
          challenge4096: { level: false, not_lock: false },
          challenge8192: { level: false, not_lock: false },
          updatedAt: db.serverDate()
        }
      })
      userDoc = { _id: addRes._id, openid: openid, nickName: maskNickName(openid) }
    } catch (createErr) {
      console.error('[saveReview] auto-create failed:', createErr.message)
      return { code: -1, message: 'user not found and create failed' }
    }
  }

  const now = new Date()
  const dateStr = now.getFullYear() + '-' +
    String(now.getMonth() + 1).padStart(2, '0') + '-' +
    String(now.getDate()).padStart(2, '0') + ' ' +
    String(now.getHours()).padStart(2, '0') + ':' +
    String(now.getMinutes()).padStart(2, '0')

  const reviewDoc = {
    userId: userDoc._id,
    openid: openid,
    nickName: userDoc.nickName || '玩家',
    score: score,
    comment: comment,
    createdAt: dateStr,
    createdTs: now.getTime()
  }

  try {
    const addRes = await reviewsCol.add({ data: reviewDoc })
    return { code: 0, message: 'ok', data: { reviewId: addRes._id } }
  } catch (addErr) {
    console.error('[saveReview] add review failed:', addErr.message)
    return { code: -1, message: addErr.message || 'save failed' }
  }
}

async function getReviewsImpl(openid, event) {
  const limit = Math.min(event.limit || 50, 100)

  let list = []
  let totalCount = 0
  let sum = 0
  let userReviewed = false

  try {
    const countRes = await reviewsCol.count()
    totalCount = countRes.total || 0

    const res = await reviewsCol.orderBy('createdTs', 'desc').limit(limit).get()

    if (res.data) {
      for (let i = 0; i < res.data.length; i++) {
        const r = res.data[i]
        const sc = r.score || 0
        sum += sc
        if (r.openid === openid) userReviewed = true

        let t = r.createdAt || ''
        if (t.length > 16) t = t.substring(5, 16)

        list.push({
          nickName: r.nickName || '玩家',
          score: sc,
          comment: r.comment || '',
          time: t
        })
      }
    }
  } catch (e) {
    console.warn('[getReviews] query failed:', e.message)
  }

  const average = totalCount > 0 ? (sum / list.length) : 0
  return {
    code: 0,
    message: 'ok',
    data: {
      list: list,
      total: totalCount,
      average: average,
      userReviewed: userReviewed
    }
  }
}

exports.main = async (event, context) => {
  const wxContext = cloud.getWXContext()
  const openid = wxContext.OPENID

  console.log('[gameApi] action=', event.action, 'openid=', openid)

  try {
    switch (event.action) {
      case 'login': return await loginImpl(openid)
      case 'getUserData': return await getUserDataImpl(openid)
      case 'updateGame': return await updateGameImpl(openid, event)
      case 'getRanking': return await getRankingImpl(openid, event)
      case 'saveReview': return await saveReviewImpl(openid, event)
      case 'getReviews': return await getReviewsImpl(openid, event)
      default: return { code: -1, message: 'unknown action: ' + event.action }
    }
  } catch (err) {
    console.error('[gameApi] error:', err)
    return { code: -1, message: err.message || 'server error' }
  }
}
